extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var checker_script := await instantiate_script("res://plugin_checker.gd")
	if not check("checker_script", checker_script != null, "Lo script res://plugin_checker.gd deve potersi istanziare"):
		return

	var valid_res: bool = call_if_exists(checker_script, "verify_plugin_register", ["res://assets/plugin_register.json"], false)
	check("valid_register", valid_res == true, "verify_plugin_register deve restituire true per il registro valido creato")

	var non_existing_res: bool = call_if_exists(checker_script, "verify_plugin_register", ["res://assets/non_existing.json"], true)
	check("file_not_found", non_existing_res == false, "verify_plugin_register deve restituire false se il file non esiste")

