class_name PluginChecker
extends RefCounted


func verify_plugin_register(path: String) -> bool:
	if not FileAccess.file_exists(path):
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		return false

	var content := file.get_as_text()
	var json_data: Variant = JSON.parse_string(content)
	if not json_data is Dictionary:
		return false

	var info: Dictionary = json_data
	var license: String = String(info.get("license", ""))
	var godot_version: String = String(info.get("godot_version", ""))
	var last_update: String = String(info.get("last_update", ""))
	var has_docs: bool = bool(info.get("has_documentation", false))

	if license.is_empty() or license == "Sconosciuta":
		return false

	if godot_version != "4.7":
		return false

	if last_update.is_empty():
		return false

	if not has_docs:
		return false

	return true
